import { stderr } from 'node:process';
import { onExit } from 'signal-exit';
const ST = '\x1b\\';
export const HEARTBEAT_INTERVAL_MS = 5_000;
// Ora clobbers stderr.write and messes with OSC output.
// Keep the original writer so progress sequences do not collide.
const writeToStderr = stderr.write.bind(stderr);
const STATES = {
    clear: 0,
    normal: 1,
    error: 2,
    paused: 4,
    busy: 3,
};
let exitHookRegistered = false;
let heartbeat;
let heartbeatSequence;
function stopHeartbeat() {
    if (heartbeat)
        clearInterval(heartbeat);
    heartbeat = undefined;
    heartbeatSequence = undefined;
}
function startHeartbeat(sequence) {
    heartbeatSequence = sequence;
    if (heartbeat)
        return;
    heartbeat = setInterval(() => {
        if (stderr.isTTY && heartbeatSequence)
            writeToStderr(heartbeatSequence);
    }, HEARTBEAT_INTERVAL_MS);
    heartbeat.unref();
}
function write(state, value = 0) {
    if (!stderr.isTTY) {
        stopHeartbeat();
        return;
    }
    if (!exitHookRegistered) {
        exitHookRegistered = true;
        function clear() {
            stopHeartbeat();
            writeToStderr(`\x1b]9;4;0;0${ST}`);
        }
        // arc/utils SIGINT handler clobbers our signal-exit; luckily it then calls process.exit()
        process.once('exit', clear); // triggered by arc/utils SIGINT handler
        onExit(clear); // triggered by all other exit paths
    }
    const sequence = `\x1b]9;4;${STATES[state]};${Math.round(value)}${ST}`;
    const active = state === 'normal' || state === 'paused' || state === 'busy';
    if (!active)
        stopHeartbeat();
    writeToStderr(sequence);
    if (active)
        startHeartbeat(sequence);
}
export function showProgress(percent) {
    write('normal', Math.max(0, Math.min(100, percent)));
}
export function showBusy() {
    write('busy');
}
export function showError() {
    write('error', 100);
}
export function showPaused(percent) {
    write('paused', Math.max(0, Math.min(100, percent)));
}
export function clearProgress() {
    write('clear');
}
